// Configuration defaults
const DEFAULT_TEMP = 22.5;
const MIN_TEMP = 19.0;
const MAX_TEMP = 26.5;
const MAX_DRIFT_STEP = 0.3; // Maximum change per message

// Retrieve the last known reading from node context
let lastTemp = context.get('lastTemp') ?? DEFAULT_TEMP;

let currentTemp;

// Check if incoming MQTT payload has a valid number or numeric string
let rawT = msg.payload && typeof msg.payload === 'object' ? parseFloat(msg.payload.T) : NaN;

if (!isNaN(rawT)) {
    currentTemp = rawT;
} else {
    // Generate a gradual random walk: step between -0.3 and +0.3
    let step = (Math.random() * (MAX_DRIFT_STEP * 2) - MAX_DRIFT_STEP);
    currentTemp = lastTemp + step;

    // Soft pull toward default to prevent runaway drifting
    currentTemp += (DEFAULT_TEMP - currentTemp) * 0.05;

    // Clamp within min/max bounds
    currentTemp = Math.max(MIN_TEMP, Math.min(MAX_TEMP, currentTemp));
}

// Format final value and calculate actual change from last reading
let value = parseFloat(currentTemp.toFixed(1));
let delta = parseFloat((value - lastTemp).toFixed(1));

// Store for next message cycle
context.set('lastTemp', value);

// Status evaluation
let status;
if (value < 22) status = "Too Cold";
else if (value <= 26) status = "Comfortable";
else if (value <= 29) status = "Too Warm";
else status = "Too Hot";

// Color evaluation
let color;
if (value < 22) color = '#89CFF0';
else if (value <= 26) color = '#1D9E75';
else if (value <= 29) color = '#EF9F27';
else color = '#D85A30';

// Assign final payload
msg.payload = {
    value: value,
    delta: delta,
    status: status,
    color: color
};

return msg;

// Configuration defaults for relative humidity (%)
const DEFAULT_HUMIDITY = 50.0;
const MIN_HUMIDITY = 25.0;
const MAX_HUMIDITY = 80.0;
const MAX_DRIFT_STEP = 0.8; // Small realistic drift per tick

// Retrieve previous reading from context memory
let lastHumidity = context.get('lastHumidity') ?? DEFAULT_HUMIDITY;

let currentHumidity;

// Check if incoming MQTT payload has a valid number or numeric string for H
let rawH = msg.payload && typeof msg.payload === 'object' ? parseFloat(msg.payload.H) : NaN;

if (!isNaN(rawH)) {
    currentHumidity = rawH;
} else {
    // Gradual random walk: step between -0.8% and +0.8%
    let step = (Math.random() * (MAX_DRIFT_STEP * 2) - MAX_DRIFT_STEP);
    currentHumidity = lastHumidity + step;

    // Gentle pull back toward 50% to prevent continuous runaway drift
    currentHumidity += (DEFAULT_HUMIDITY - currentHumidity) * 0.05;

    // Clamp within realistic demo bounds
    currentHumidity = Math.max(MIN_HUMIDITY, Math.min(MAX_HUMIDITY, currentHumidity));
}

// Format integer value and calculate actual delta from previous cycle
let value = parseInt(currentHumidity.toFixed(0), 10);
let delta = parseFloat((currentHumidity - lastHumidity).toFixed(1));

// Store updated value for the next message
context.set('lastHumidity', currentHumidity);

// Status evaluation
let status;
if (value < 30) status = "Too Dry";
else if (value <= 60) status = "Comfortable";
else if (value <= 70) status = "Too Humid";
else status = "Dangerous";

