};

return msg;

// Configuration defaults for CO2 (ppm)
const DEFAULT_CO2 = 650;
const MIN_CO2 = 420;        // Fresh outdoor ambient baseline
const MAX_CO2 = 1400;       // Upper bound for indoor demo
const MAX_DRIFT_STEP = 15;  // Max change in ppm per tick

// Retrieve previous reading from context memory
let lastCO2 = context.get('lastCO2') ?? DEFAULT_CO2;

let currentCO2;

// Check if incoming MQTT payload has a valid number or numeric string for CO2
let rawCO2 = msg.payload && typeof msg.payload === 'object' ? parseFloat(msg.payload.CO2) : NaN;

if (!isNaN(rawCO2)) {
    currentCO2 = rawCO2;
} else {
    // Gradual random walk: step between -15 and +15 ppm
    let step = (Math.random() * (MAX_DRIFT_STEP * 2) - MAX_DRIFT_STEP);
    currentCO2 = lastCO2 + step;

    // Gentle pull toward 650 ppm to avoid runaway drift
    currentCO2 += (DEFAULT_CO2 - currentCO2) * 0.04;

    // Clamp within realistic demo bounds
    currentCO2 = Math.max(MIN_CO2, Math.min(MAX_CO2, currentCO2));
}

// Format integer value and calculate delta from previous cycle
let value = parseInt(currentCO2.toFixed(0), 10);
let delta = parseInt((currentCO2 - lastCO2).toFixed(0), 10);

// Store updated value for the next message
context.set('lastCO2', currentCO2);

// Status evaluation
let status;
if (value < 600) status = "Excellent";
else if (value <= 800) status = "Good";
else if (value <= 1200) status = "Needs Ventilation";
else status = "Dangerous";

